from pathlib import Path

from engine_params.src.gcode.process.support_l2_metrics import (
    analyze_support_gcode,
    canonical_expected,
    metric_matches,
)


def test_analyze_support_gcode_extracts_semantic_metrics(tmp_path: Path):
    gcode = tmp_path / "support.gcode"
    gcode.write_text(
        """; HEADER_BLOCK_START
; generated by test
; HEADER_BLOCK_END
; EXECUTABLE_BLOCK_START
M83
T0
;LAYER_CHANGE
;Z:0.2
G1 X0 Y0 F6000
;TYPE:Support
G1 X10 Y0 E1 F3600
;TYPE:Support interface
G1 X10 Y10 E2 F4800
; EXECUTABLE_BLOCK_END
; CONFIG_BLOCK_START
support_speed = 999
; CONFIG_BLOCK_END
""",
        encoding="utf-8",
    )

    metrics = analyze_support_gcode(gcode)

    assert metrics["role.Support.move_count"] == 1
    assert metrics["role.Support.path_length"] == 10.0
    assert metrics["role.Support.speed_p50"] == 60.0
    assert metrics["role.Support interface.speed_p50"] == 80.0
    assert metrics["role.Support total.move_count"] == 2


def test_metric_matches_uses_exact_counts_and_tolerant_geometry():
    assert metric_matches("role.Support.move_count", 10, 10)
    assert not metric_matches("role.Support.move_count", 11, 10)
    assert metric_matches("role.Support.path_length", 100.5, 100.0)
    assert not metric_matches("role.Support.path_length", 103.0, 100.0)


def test_metric_ranges_and_numeric_expected_values_are_stable():
    assert canonical_expected(2) == canonical_expected("2")
    assert canonical_expected(0.20) == canonical_expected("0.2")
    assert metric_matches(
        "role.Support.path_length",
        112.0,
        {"min": 100.0, "max": 110.0},
        relative_tolerance=0.02,
    )
    assert not metric_matches(
        "role.Support.path_length",
        113.0,
        {"min": 100.0, "max": 110.0},
        relative_tolerance=0.02,
    )
